	/* @Override */
	public Collection<VTMatch> getMatches(VTAssociation association) {
		List<VTMatch> list = new();
		try
{
    using (Closeable c = @lock.read())
    {

			VTAssociationDB associationDB = (VTAssociationDB) association;
			if (associationDB == null) {
